<script setup lang="ts">import {ref,computed} from 'vue';import type {Workspace} from '../stores/workspace';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import {create} from '../api/arcs';import {useAsync} from '../hooks/useAsync';const props=defineProps<{data:Workspace;canWrite:boolean;refresh:()=>Promise<void>}>();const dataset=ref(''),arcId=ref(''),source=ref(''),target=ref(''),capacity=ref(1),minutes=ref(1);const ds=computed(()=>props.data.datasets.find(d=>d.id===dataset.value)||props.data.datasets[0]);const arcs=computed(()=>props.data.arcs.filter(a=>a.dataset_id===ds.value?.id).sort((a,b)=>a.arc_id.localeCompare(b.arc_id)));const {busy,error,execute}=useAsync();async function submit(){await execute(async()=>{await create({dataset_id:ds.value?.id,arc_id:arcId.value,source:source.value||ds.value?.nodes[0]?.node_id,target:target.value||ds.value?.nodes[ds.value.nodes.length-1]?.node_id,capacity:capacity.value,travel_minutes:minutes.value});arcId.value='';await props.refresh()})};</script><template><PageHeading code="03 / CAPACITY & TIME" title="同向平行边，也要逐条入账。" description="容量为非负整数箱/小时，时长为非负分钟。零容量边保留在台账，但不允许进入最短可达路径。"/><section class="paper"><div class="section-heading"><h2>逐边容量台账</h2><select aria-label="边台账网络" :value="ds?.id" @change="dataset=($event.target as HTMLSelectElement).value;source='';target=''"><option v-for="d in data.datasets" :key="d.id" :value="d.id">{{d.name}}</option></select></div><div class="table-scroll"><table><thead><tr><th>独立边ID</th><th>源 → 目标</th><th>容量 / 箱每小时</th><th>时长 / 分钟</th></tr></thead><tbody><tr v-for="a in arcs" :key="a.id"><td><b>{{a.arc_id}}</b></td><td>{{a.source}} → {{a.target}}</td><td>{{a.capacity}}</td><td>{{a.travel_minutes.toFixed(3)}}</td></tr></tbody></table></div></section><section class="paper" v-if="canWrite"><h2>新增一条独立边</h2><form class="arc-form" @submit.prevent="submit"><label>新边ID<input aria-label="新边ID" required v-model="arcId"/></label><label>源节点<select aria-label="边源节点" :value="source||ds?.nodes[0]?.node_id" @change="source=($event.target as HTMLSelectElement).value"><option v-for="n in ds?.nodes" :key="n.node_id" :value="n.node_id">{{n.node_id}} · {{n.label}}</option></select></label><label>目标节点<select aria-label="边目标节点" :value="target||ds?.nodes[ds.nodes.length-1]?.node_id" @change="target=($event.target as HTMLSelectElement).value"><option v-for="n in ds?.nodes" :key="n.node_id" :value="n.node_id">{{n.node_id}} · {{n.label}}</option></select></label><label>容量 / 箱每小时<input aria-label="边容量" type="number" min="0" max="1000000" step="1" v-model.number="capacity"/></label><label>时长 / 分钟<input aria-label="边时长" type="number" min="0" max="1000000" step="any" v-model.number="minutes"/></label><button :disabled="busy">保存独立边</button></form><Notice v-if="error" error>{{error}}</Notice><p class="caption">新增边不会改变已锁定的推演快照；如需纳入比较，请新建停用方案。端点相同也不得复用旧边ID。</p></section></template>
